      when: { all: [{ f: "way", eq: "تخصص دیگران" }, { f: "x_method", eq: "معتبر" }, { f: "x_comp", eq: "احراز شده" }, { f: "chain", eq: "تک‌منبع" }, { f: "x_field", eq: "نامعلوم" }] }, eff: "cap", cap: 50,
      err: "اطمینانِ بیش از ½ به یافتهٔ یک پژوهشِ تنها از رشته/مجله‌ای که نرخِ درستیِ پژوهش‌هایش سنجیده نشده، فقط چون روش معتبر و کارشناس صاحب‌صلاحیت است",
      fix: "اگر کنشگر نرخِ تکرارپذیریِ همان رشته و مجله را می‌جست (یا منتظرِ تکرارِ مستقل می‌ماند)، پیش از آن اطمینانش را از ½ بالاتر نمی‌برد.",
